    private

    def instrument(name)
      return yield unless @logger

      started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      begin
        yield
      ensure
        elapsed = (Process.clock_gettime(Process::CLOCK_MONOTONIC) - started) * 1000
        @logger.debug { format('%<class>s#%<name>s (%<ms>.1fms)', class: self.class.name, name: name, ms: elapsed) }
      end
    end

    def with_client(name)
      instrument(name) do
        @db.with do |client|
          client.extend(ConnectionState) unless client.is_a?(ConnectionState)
          yield client
        end
      end
    end

    # Formats one row for LOAD DATA ... FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' ESCAPED BY '\\'.
    def csv_line(values)
      fields = values.map do |value|
        case value
        when nil then '\N'
        when true then '1'
        when false then '0'
        when Time then value.strftime('%Y-%m-%d %H:%M:%S.%6N')
        else value.to_s.gsub('\\') { '\\\\' }
        end
      end
      CSV.generate_line(fields)
    end

    def slice_placeholders(values)
      values.empty? ? 'NULL' : Array.new(values.size, '?').join(', ')
    end
